{
 "appearance_facts": [
  {
   "location": "Title area, top left",
   "fact": "The chart title reads 'Falling Respiratory Infection Cases in Sentinel Sites from 2012 to 2023'. This is a printed statement about the trend, not a data point."
  },
  {
   "location": "Plot area",
   "fact": "A single purple line series connects data points for each year from 2012 to 2023. The line generally trends upward from the left (2012) to the right (2023), with a peak in 2022."
  },
  {
   "location": "Data point for 2012",
   "fact": "The line starts at a value slightly above the 700 grid line."
  },
  {
   "location": "Data point for 2015",
   "fact": "The line shows a local dip, falling below the 2014 peak but remaining above the 1000 level (estimated between 1100-1200)."
  },
  {
   "location": "Data point for 2022",
   "fact": "The line reaches its highest point on the chart, significantly above the 2800 grid line (estimated near 3000-3100)."
  },
  {
   "location": "Data point for 2023",
   "fact": "The line ends at a high value, slightly lower than the 2022 peak but still well above the 2800 grid line."
  }
 ],
 "printed_facts": [
  {
   "location": "Y-axis label",
   "fact": "The vertical axis is labeled 'Respiratory infection cases'."
  },
  {
   "location": "Y-axis ticks",
   "fact": "Visible tick labels are 0, 700, 1400, 2100, and 2800."
  },
  {
   "location": "X-axis label",
   "fact": "The horizontal axis is labeled 'Year'."
  },
  {
   "location": "X-axis ticks",
   "fact": "Visible tick labels are 2012, 2013, 2014, 2015, 2016, 2017, 2018, 2019, 2020, 2021, 2022, and 2023."
  },
  {
   "location": "Subtitle",
   "fact": "The text below the title reads 'Sentinel surveillance record shown in the dashboard summary'."
  }
 ],
 "public_definitions": [
  "Goal: Review the respiratory infection surveillance dashboard and select the operational route that best fits the overall case pattern for this record.",
  "Options: 'Route the record to increasing-activity follow-up', 'Route the record to easing-activity follow-up', 'Route the record to standard surveillance monitoring'."
 ],
 "uncertain": [
  "The exact numerical value for each year is not printed on the data points; values are estimated from grid lines.",
  "The title claims the cases are 'Falling', which contradicts the visual upward trend of the line graph from 2012 to 2022."
 ]
}
